namespace Grobots_motor_driver {
	/************************************************************************************************************************************************
	* micro:bit motor driver blocks 
	************************************************************************************************************************************************/
    /*Note that Forward and reverse are slightly arbitrary, as it depends on how the motor is wired...*/
    export enum MotorDirection {
        //% block="forward"
        Forward,
        //% block="reverse"
        Reverse
    }

    export enum Motors {
        //%blockId=Grobots_motordriver_motor_one
        //% block="motor 1"
        Motor1,
        //%blockId=Grobots_motordriver_motor_two
        //% block="motor 2"
        Motor2,
         //%blockId=Grobots_motordriver_motor_two
        //% block="motor 3"
        Motor3,
         //%blockId=Grobots_motordriver_motor_two
        //% block="motor 4"
        Motor4,

    }
	/**
     * Turns on motor specified by eMotors in the direction specified
     * by eDirection, at the requested speed 
     *
	 * @param motor which motor to turn on
	 * @param dir   which direction to go
	 * @param speed how fast to spin the motor
     */
    //% blockId=kitronik_motordriver_motor_on
    //% block="%motor|on direction %dir|speed %speed"
    //% speed.min=0 speed.max=100
    export function motorOn(motor: Motors, dir: MotorDirection, speed: number): void {

        let OutputVal = Math.clamp(0, 100, speed) * 10;

        switch (motor) {
            case Motors.Motor1: /*Motor 1 uses Pins 8 and 12*/
                switch (dir) {
                    case MotorDirection.Forward:
                        pins.analogWritePin(AnalogPin.P0, OutputVal);
                        pins.digitalWritePin(DigitalPin.P16, 0); /*Write the low side digitally, to allow the 3rd PWM to be used if required elsewhere*/
                        break
                    case MotorDirection.Reverse:
                        pins.analogWritePin(AnalogPin.P16, OutputVal);
                        pins.digitalWritePin(DigitalPin.P0, 0);
                        break
                }
                break;
            case Motors.Motor2: /*Motor 2 uses Pins 0 and 16*/
                switch (dir) {
                    case MotorDirection.Forward:
                        pins.analogWritePin(AnalogPin.P12, OutputVal);
                        pins.digitalWritePin(DigitalPin.P8, 0); /*Write the low side digitally, to allow the 3rd PWM to be used if required elsewhere*/
                        break
                    case MotorDirection.Reverse:
                        pins.analogWritePin(AnalogPin.P8, OutputVal);
                        pins.digitalWritePin(DigitalPin.P12, 0);
                        break
                }
                break;
            case Motors.Motor3: /*Motor 3 uses Pins 14  and 15*/
                switch (dir) {
                    case MotorDirection.Forward:
                        pins.analogWritePin(AnalogPin.P1, OutputVal);
                        pins.digitalWritePin(DigitalPin.P2, 0); /*Write the low side digitally, to allow the 3rd PWM to be used if required elsewhere*/
                        break
                    case MotorDirection.Reverse:
                        pins.analogWritePin(AnalogPin.P2, OutputVal);
                        pins.digitalWritePin(DigitalPin.P1, 0);
                        break
                }
                break;
                 case Motors.Motor4: /*Motor 4 uses Pins 1  and 2*/
                switch (dir) {
                    case MotorDirection.Forward:
                        pins.analogWritePin(AnalogPin.P14, OutputVal);
                        pins.digitalWritePin(DigitalPin.P15, 0); /*Write the low side digitally, to allow the 3rd PWM to be used if required elsewhere*/
                        break
                    case MotorDirection.Reverse:
                        pins.analogWritePin(AnalogPin.P15, OutputVal);
                        pins.digitalWritePin(DigitalPin.P14, 0);
                        break
                }
                break;
        }
    }
	/**
     * Turns off the motor specified by eMotors
     * @param motor :which motor to turn off
     */
    //% blockId=kitronik_motordriver_motor_off
    //%block="turn off %motor"
    export function motorOff(motor: Motors): void {
        switch (motor) {
            case Motors.Motor1:
                pins.digitalWritePin(DigitalPin.P0, 0);
                pins.digitalWritePin(DigitalPin.P16, 0);
                break
            case Motors.Motor2:
                pins.digitalWritePin(DigitalPin.P12, 0);
                pins.digitalWritePin(DigitalPin.P8, 0);
                break
            case Motors.Motor3:
                pins.digitalWritePin(DigitalPin.P1, 0);
                pins.digitalWritePin(DigitalPin.P2, 0);
                break
            case Motors.Motor4:
                pins.digitalWritePin(DigitalPin.P14, 0);
                pins.digitalWritePin(DigitalPin.P15, 0);
                break
        }
    }
}
